// authService.js
import api from './api';

class AuthService {
    async login(email, password) {
        try {
            const response = await api.post('/auth/login', { email, password });
            console.log('Login response:', response.data);

            if (response.data.token) {
                localStorage.setItem('token', response.data.token);
                localStorage.setItem('user', JSON.stringify(response.data.user));
            }
            return response.data;
        } catch (error) {
            console.error('Login API error:', error);
            console.error('Error response:', error.response);

            if (error.response && error.response.data) {
                const errorData = error.response.data;
                throw new Error(errorData.message || 'Неверный email или пароль');
            }
            throw new Error('Ошибка подключения к серверу');
        }
    }

    async register(userData) {
        try {
            const data = { ...userData };
            const response = await api.post('/auth/register', data);
            if (response.data.token) {
                localStorage.setItem('token', response.data.token);
                localStorage.setItem('user', JSON.stringify(response.data.user));
            }
            return response.data;
        } catch (error) {
            const errorMessage = error.response?.data?.message || 'Ошибка регистрации';
            throw new Error(errorMessage);
        }
    }

    logout() {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
    }

    getCurrentUser() {
        const userStr = localStorage.getItem('user');
        if (userStr) {
            try {
                return JSON.parse(userStr);
            } catch (e) {
                console.error('Error parsing user from localStorage:', e);
                return null;
            }
        }
        return null;
    }

    getToken() {
        return localStorage.getItem('token');
    }

    isAuthenticated() {
        return !!this.getToken();
    }

    async updateProfile(userData) {
        try {
            const response = await api.put('/users/profile', userData);
            if (response.data.user) {
                localStorage.setItem('user', JSON.stringify(response.data.user));
            }
            return response.data;
        } catch (error) {
            const errorMessage = error.response?.data?.message || 'Ошибка обновления профиля';
            throw new Error(errorMessage);
        }
    }

    async changePassword(passwordData) {
        try {
            const response = await api.put('/users/change-password', passwordData);
            return response.data;
        } catch (error) {
            const errorMessage = error.response?.data?.message || 'Ошибка смены пароля';
            throw new Error(errorMessage);
        }
    }

    async deleteAccount() {
        try {
            const response = await api.delete('/users/account');
            this.logout();
            return response.data;
        } catch (error) {
            const errorMessage = error.response?.data?.message || 'Ошибка удаления аккаунта';
            throw new Error(errorMessage);
        }
    }
}

export default new AuthService();
